        self::index($pdo,'personal_planner_tasks','idx_parent_instance','ALTER TABLE personal_planner_tasks ADD INDEX idx_parent_instance(parent_task_id,user_id,task_date)');
        $module=$pdo->prepare('INSERT INTO modules(module_key,module_title,sort_order,status,created_at) VALUES(?,?,?,"active",NOW()) ON DUPLICATE KEY UPDATE module_title=VALUES(module_title),status="active"');
        $module->execute(['personal_planner','برنامه کاری من',330]);$module->execute(['personal_planner.reports_all','مشاهده گزارش پلنر کاربران',331]);
