    private static function column(PDO $pdo,string $table,string $column,string $definition):void{$q=$pdo->prepare('SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME=? AND COLUMN_NAME=?');$q->execute([$table,$column]);if(!(int)$q->fetchColumn())$pdo->exec("ALTER TABLE `{$table}` ADD `{$column}` {$definition}");}
    private static function index(PDO $pdo,string $table,string $index,string $sql):void{$q=$pdo->prepare('SELECT COUNT(*) FROM information_schema.STATISTICS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME=? AND INDEX_NAME=?');$q->execute([$table,$index]);if(!(int)$q->fetchColumn())$pdo->exec($sql);}
    private static function widen(PDO $pdo,string $table,string $column,string $target,string $definition):void{$q=$pdo->prepare('SELECT COLUMN_TYPE FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME=? AND COLUMN_NAME=?');$q->execute([$table,$column]);$type=strtolower((string)$q->fetchColumn());if($type!==strtolower($target))$pdo->exec("ALTER TABLE `{$table}` MODIFY `{$column}` {$definition}");}
}
